import{z as p,x as A,o as t,c as d,q as s,j as o,D as n,d as r,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Turing 可计算","description":"","frontmatter":{"title":"Turing 可计算","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/turing-1936-paper.md","filePath":"cs/turing-1936-paper.md","lastUpdated":1791413859000}'),B={name:"cs/turing-1936-paper.md"};function u(h,a,m,c,g,P){const E=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=s('<h1 id="turing-可计算" tabindex="-1">Turing 可计算 <a class="header-anchor" href="#turing-可计算" aria-label="Permalink to &quot;Turing 可计算&quot;">​</a></h1><div class="epigraph"><p>把「一步机械手续」写成在无限纸带上的有限状态动作；不可判定随之成为定理，而不是口号。</p><footer>—— Turing, On Computable Numbers, with an Application to the Entscheidungsproblem, Proc. London Math. Soc. 1936</footer></div><p>本篇是文献对照附录的第一课，不插入主干课序：附录只对照文献，不推进课序。主干已在<a href="/cs/stored-program">存储程序</a>、<a href="/cs/p-vs-np">P 与 NP</a>里用过「有限步骤的机械过程」与判定问题；这里对照 <strong>Turing 1936 原文的问题</strong>：希尔伯特判定问题能否有统一手续，以及用机器把「可计算」钉死。不重做停机证明的全部细节，也不把本篇插回比特课之前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干从比特与指令走下来，默认「程序会停或我们可以不管停」。Turing 要的缺口是先定义<strong>哪一类实数/函数算可计算</strong>：有限状态、无限带、逐步读写。Entscheidungsproblem 是：一阶逻辑有效式有没有算法。原文的贡献是模型加否定答案，不是发明电子计算机。</p><p><span class="marginnote">Church 的 λ 可定义与 Turing 机事后被证明等价。主干算法课用的是 RAM/高级语言直觉；本附录只对照纸带模型如何让「手续」变成数学对象。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>机器：状态有限，带格是符号，转移是局部的。可计算数：小数位由机器依次写出。通用机：把转移表编码到带上，一台机器模拟另一台——主干<a href="/cs/stored-program">存储程序</a>的观念亲戚，但 1936 还没有 EDVAC 的报告语言。停机、判定问题由此可以对角化。</p>',8)),(t(),o(l,null,{default:n(()=>[i(E,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TM%5B%22%E6%9C%89%E9%99%90%E7%8A%B6%E6%80%81%20%2B%20%E7%BA%B8%E5%B8%A6%22%5D%20--%3E%20COMP%5B%22%E5%8F%AF%E8%AE%A1%E7%AE%97%22%5D%0A%20%20TM%20--%3E%20UNDEC%5B%22%E5%88%A4%E5%AE%9A%E9%97%AE%E9%A2%98%E6%97%A0%E7%AE%97%E6%B3%95%22%5D%0A%20%20COMP%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E7%AE%97%E6%B3%95%E4%B8%8E%20P%2FNP%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[r("有了模型，后文才能说 P、NP、不可判定。主干"),e("a",{href:"/cs/p-vs-np"},"P 与 NP"),r("已经用多项式时间当资源；1936 还没有渐近记号课里的那一套，只区分「有手续 / 无手续」。通用机让「程序即数据」在数学上先出现，工程上的存放由下一篇 EDVAC 对照。")],-1)),a[5]||(a[5]=e("p",null,"通用机如何把「程序也是数据」落到纸带上：",-1)),(t(),o(l,null,{default:n(()=>[i(E,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%90%8C%E4%B8%80%E6%A0%B9%E7%BA%B8%E5%B8%A6%E5%88%86%E5%8C%BA%22%5D%20--%3E%20P%5B%22%E7%BC%96%E7%A0%81%E5%8C%BA%3A%20%E6%9C%BA%E5%99%A8%20M%20%E7%9A%84%E8%BD%AC%E7%A7%BB%E8%A1%A8%22%5D%0A%20%20T%20--%3E%20I%5B%22%E8%BE%93%E5%85%A5%E5%8C%BA%3A%20M%20%E7%9A%84%E5%88%9D%E5%A7%8B%E5%B8%A6%E5%86%85%E5%AE%B9%22%5D%0A%20%20P%20--%3E%20U%5B%22%E9%80%9A%E7%94%A8%E6%9C%BA%20U%20%E9%80%90%E6%A0%BC%E6%89%AB%E6%8F%8F%22%5D%0A%20%20I%20--%3E%20U%0A%20%20U%20--%3E%20S%5B%22%E6%8C%89%20M%20%E7%9A%84%E8%A7%84%E5%88%99%E6%94%B9%E5%86%99%E4%B8%8E%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20S%20--%3E%20EQ%5B%22%E8%BE%93%E5%87%BA%20%3D%20%E7%9C%9F%E6%9C%BA%20M%20%E8%BF%90%E8%A1%8C%E7%9A%84%E7%BB%93%E6%9E%9C%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">直觉类比：通用机像一位「念菜谱的厨子」——纸带前半段是菜谱（另一台机器的转移表），后半段是食材（输入）。它不必记住每道菜怎么做，只按菜谱逐条念、逐条做；「菜谱本身就是写在纸上的数据」正是存储程序的数学前身。</span></p><p><span class="marginnote">术语翻译：Entscheidungsproblem（判定问题）= 「给一条一阶逻辑陈述，是否存在一套万有的机械手续判定它有效」。Turing 的答案是否定的：若这套手续存在，把它喂给通用机就能判定任意机器停不停，与对角线构造矛盾。</span></p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>若把 1936 插进比特课之后，读者会以为本栏第一课是可计算性。主干第一课是区分与编码；可计算性是算法课后段才需要的尺子。附录只对照原文如何把手续写成机器，以及主干停机/复杂性已经取走的那一层定义。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 1936 与 1950 年《计算机器与智能》混成一篇。也不要在附录里开递归论层级。下一篇对照 von Neumann 如何把存储程序写成工程草案。</p><p>本附录不重画有限自动机与正则——那是编译课词法。Turing 机比正则强，主干正则课不需要本篇插入。</p><p><span class="marginnote">常见误区：把「可计算」与「多项式时间可计算」当成同一句话。1936 只区分<strong>有没有</strong>手续（可判定）；P/NP 的尺子量的是手续<strong>贵不贵</strong>。一个指数时间但必然停止的算法，仍然属于「可计算」。</span></p><p>停机问题的对角线与<a href="/cs/p-vs-np">P 与 NP</a>的资源界限不是同一层：一个是有没有手续，一个是手续有多贵。</p><p>对照结束应回到主干<a href="/cs/p-vs-np">P 与 NP</a>与<a href="/cs/stored-program">存储程序</a>，而不是用纸带重讲 RISC-V。本篇不插入比特课之后。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Turing 1936：可计算 = 纸带上的有限手续；判定问题无解。</li><li>通用机是存储程序的数学亲戚，不是 EDVAC。</li><li>主干 P/NP 与存储程序课已取用观念，本篇不插入课序。</li><li>出处：Turing, 1936, <em>Proc. London Math. Soc.</em>。</li></ul>',12))])}const C=p(B,[["render",u]]);export{f as __pageData,C as default};
